      const result = spawnSync(
        'node',
        [CLI_PATH, 'ralph', '--dry-run', '--adapter', 'claude-code-acp'],
        {
          cwd: tempDir,
          encoding: 'utf-8',
          timeout: 30000,
          env: { ...process.env, KSPEC_AUTHOR: '@test' },
