      // Prefix should appear at most once per line
      for (const line of output.split('\n')) {
        const prefixCount = (line.match(/\[TEST\]/g) || []).length;
        expect(prefixCount, `Line has doubled prefix: ${line}`).toBeLessThanOrEqual(1);
      }
    });

