+/**
+ * Format a section as a compact summary + CLI fetch command.
+ * Intended for subagent prompts to avoid embedding full JSON payloads.
+ */
+export function formatCompactSection(
+  data: Record<string, unknown>,
+  label: string,
+  fetchCmd: string,
